import { lazy } from 'react';
import { Banknote as IcBanknote, ClipboardCheck as IcClipboardCheck, ListChecks as IcListChecks, Receipt as IcReceipt } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Travel Expenses — hub page for the Travel Desk menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 4 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'TravelExpenseCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const ExpenseClaims = lazy(() => import('./ExpenseClaims'));
const TravelExpenses = lazy(() => import('./TravelExpenses'));
const ExpenseReview = lazy(() => import('./ExpenseReview'));
const TravelPayment = lazy(() => import('./TravelPayment'));

export const TABS = [
  { id: 'claims', label: 'Expense Claims', icon: IcReceipt, page: 'ExpenseClaims', Component: ExpenseClaims },
  { id: 'expenses', label: 'Trip Expenses', icon: IcListChecks, page: 'TravelExpenses', Component: TravelExpenses },
  { id: 'review', label: 'Expense Review', icon: IcClipboardCheck, page: 'ExpenseReview', Component: ExpenseReview },
  { id: 'payment', label: 'Payment', icon: IcBanknote, page: 'TravelPayment', Component: TravelPayment },
];

export default function TravelExpenseCenter({ setPage }) {
  return (
    <TabHub
      icon={IcReceipt}
      eyebrow="Travel Desk"
      title="Travel Expenses"
      subtitle="Claims and the trip expense register, with the finance review and payment queues"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
